// "Find your next great nonfiction" — a browsable index of prize-winning nonfiction,
// built from the Book Prize Index (https://book-prize-index.vercel.app, CC-BY-4.0).
//
// The dataset is bundled (src/data/awards.dataset, regenerated by scripts/build-awards.mjs)
// rather than fetched, so this endpoint has no upstream dependency, no scrape and no
// failure mode beyond our own code. It is nonfiction-only by nature: the index tracks
// prizes like the Pulitzer, Bancroft, Baillie Gifford and Wolfson — there is no Booker
// or Hugo in here, which is exactly what makes it a good answer to "what nonfiction
// should I read next".
//
// The dataset has no cover art (only WorldCat/OpenLibrary links), so covers are
// resolved on demand against Apple Books — see resolveCover + the cover route.

import raw from "./data/awards.dataset";

interface RawEntry {
  i: number;
  t: string;
  a: string[];
  y: number;
  s: string;
  /** [programId, categoryName, year, status] */
  w: [string, string, number, string][];
}

interface RawDataset {
  v: string;
  programs: { id: string; n: string; o: string; g: string; u: string }[];
  subjects: string[];
  books: RawEntry[];
}

export interface AwardCredit {
  program: string;
  programName: string;
  category: string;
  year: number;
  status: string;
}

export interface AwardBook {
  id: number;
  title: string;
  authors: string[];
  year: number;
  subject: string;
  awards: AwardCredit[];
}

export interface AwardProgram {
  id: string;
  name: string;
  organization: string;
  geography: string;
  url: string;
  count: number;
}

export const STATUSES = ["winner", "co_winner", "finalist", "shortlist", "longlist", "honorable_mention"] as const;
export type AwardStatus = (typeof STATUSES)[number];
const STATUS_SET = new Set<string>(STATUSES);

// Parsed once per isolate, on first use. The module-level `raw` is just a string
// until something actually asks for the data.
let cache: RawDataset | null = null;
function dataset(): RawDataset {
  if (!cache) cache = JSON.parse(raw) as RawDataset;
  return cache;
}

let programIndex: Map<string, { n: string; o: string; g: string; u: string }> | null = null;
function programs(): Map<string, { n: string; o: string; g: string; u: string }> {
  if (!programIndex) programIndex = new Map(dataset().programs.map((p) => [p.id, p]));
  return programIndex;
}

// Lowercased "title author" per book, built once, so text filtering is a substring
// scan over 9.5k short strings instead of re-lowercasing on every keystroke.
let haystack: string[] | null = null;
function searchIndex(): string[] {
  if (!haystack) haystack = dataset().books.map((b) => `${b.t} ${b.a.join(" ")}`.toLowerCase());
  return haystack;
}

export const datasetVersion = (): string => dataset().v;
export const subjects = (): string[] => dataset().subjects;

function toBook(entry: RawEntry): AwardBook {
  const progs = programs();
  return {
    id: entry.i,
    title: entry.t,
    authors: entry.a,
    year: entry.y,
    subject: entry.s,
    awards: entry.w.map(([program, category, year, status]) => ({
      program,
      programName: progs.get(program)?.n ?? program,
      category,
      year,
      status,
    })),
  };
}

export function programList(): AwardProgram[] {
  const counts = new Map<string, number>();
  for (const b of dataset().books) {
    // A book can place in several categories of the same prize; count it once.
    for (const id of new Set(b.w.map((w) => w[0]))) counts.set(id, (counts.get(id) ?? 0) + 1);
  }
  return dataset()
    .programs.map((p) => ({ id: p.id, name: p.n, organization: p.o, geography: p.g, url: p.u, count: counts.get(p.id) ?? 0 }))
    .filter((p) => p.count > 0)
    .sort((a, b) => b.count - a.count || a.name.localeCompare(b.name));
}

export interface AwardQuery {
  program?: string | null;
  subject?: string | null;
  status?: string | null;
  decade?: string | null;
  q?: string | null;
  sort?: string | null;
  page?: number;
  limit?: number;
}

function matches(entry: RawEntry, i: number, f: AwardQuery): boolean {
  if (f.program && !entry.w.some((w) => w[0] === f.program)) return false;
  if (f.subject && entry.s !== f.subject) return false;
  if (f.status && !entry.w.some((w) => w[3] === f.status)) return false;
  if (f.decade) {
    const from = Number(f.decade);
    // Match on when the book was *honoured* when we know it, else publication year —
    // a 1985 book winning a 2010 prize should surface under the 2010s.
    const years = entry.w.map((w) => w[2]).filter(Boolean);
    const best = years.length ? Math.max(...years) : entry.y;
    if (!best || best < from || best >= from + 10) return false;
  }
  if (f.q && !searchIndex()[i].includes(f.q)) return false;
  return true;
}

const STATUS_WEIGHT: Record<string, number> = { winner: 0, co_winner: 1, finalist: 2, shortlist: 3, longlist: 4, honorable_mention: 5 };

const bestYear = (e: RawEntry) => {
  const years = e.w.map((w) => w[2]).filter(Boolean);
  return years.length ? Math.max(...years) : e.y || 0;
};

export function queryBooks(f: AwardQuery): { total: number; books: AwardBook[] } {
  const all = dataset().books;
  const q = f.q ? f.q.toLowerCase().trim() : null;
  const filters: AwardQuery = { ...f, q };

  const hits: RawEntry[] = [];
  for (let i = 0; i < all.length; i++) {
    if (matches(all[i], i, filters)) hits.push(all[i]);
  }

  switch (f.sort) {
    case "recent":
      hits.sort((a, b) => bestYear(b) - bestYear(a));
      break;
    case "oldest":
      hits.sort((a, b) => bestYear(a) - bestYear(b));
      break;
    case "title":
      hits.sort((a, b) => a.t.localeCompare(b.t));
      break;
    default:
      // "acclaimed" — dataset order, which build-awards.mjs already sorted by best
      // placement then number of accolades.
      break;
  }

  const limit = Math.min(Math.max(f.limit ?? 24, 1), 60);
  const page = Math.max(f.page ?? 1, 1);
  const start = (page - 1) * limit;
  return { total: hits.length, books: hits.slice(start, start + limit).map(toBook) };
}

/**
 * Random candidates for the "surprise me" pick, honouring whatever filters are active
 * so the shuffle stays inside what the reader asked for. Restricted to books that
 * actually won something — a longlisting is a weak recommendation.
 *
 * Returns several distinct candidates rather than one: the caller races their cover
 * lookups and leads with a book that actually has art, since a coverless hero is a
 * poor showcase (obscure and pre-1990 titles are often missing from Apple Books).
 */
export function randomBooks(f: AwardQuery, count = 1): AwardBook[] {
  const all = dataset().books;
  const q = f.q ? f.q.toLowerCase().trim() : null;
  const filters: AwardQuery = { ...f, q };

  const pool: RawEntry[] = [];
  for (let i = 0; i < all.length; i++) {
    const e = all[i];
    if (!e.w.some((w) => w[3] === "winner" || w[3] === "co_winner")) continue;
    if (matches(e, i, filters)) pool.push(e);
  }
  const source = pool.length ? pool : all.filter((e, i) => matches(e, i, filters));
  if (!source.length) return [];

  const picked = new Set<number>();
  const out: AwardBook[] = [];
  const wanted = Math.min(count, source.length);
  // Bounded attempts: with a tiny pool, random collisions would otherwise spin.
  for (let attempt = 0; attempt < wanted * 6 && out.length < wanted; attempt++) {
    const index = Math.floor(Math.random() * source.length);
    if (picked.has(index)) continue;
    picked.add(index);
    out.push(toBook(source[index]));
  }
  return out;
}

export function bookById(id: number): AwardBook | null {
  const all = dataset().books;
  return id >= 0 && id < all.length ? toBook(all[id]) : null;
}

export function validStatus(s: string | null): string | null {
  return s && STATUS_SET.has(s) ? s : null;
}

export function validProgram(p: string | null): string | null {
  return p && programs().has(p) ? p : null;
}

export function validSubject(s: string | null): string | null {
  return s && dataset().subjects.includes(s) ? s : null;
}

export function validDecade(d: string | null): string | null {
  if (!d || !/^\d{4}$/.test(d)) return null;
  const n = Number(d);
  return n % 10 === 0 && n >= 1900 && n <= 2030 ? d : null;
}

export function sortWeight(status: string): number {
  return STATUS_WEIGHT[status] ?? 9;
}
